We start by proving the following 2 auxiliary statements:

\begin{claim}[Composition of bounded SoS polynomials]\label{claim:basic-composition-properties}
Let $p_1(x_1, x_2)$ be a $(k_1, d_1, C_1)$-bounded SoS polynomial and $p_2(x_1, x_2)$ be a $(k_2, d_2, C_2)$-bounded SoS polynomial.  Then
\begin{enumerate}[label=(\alph*)]
    \item $p_1 + p_2$ is a $(k_1 + k_2,\,\max(d_1, d_2),\,\max(C_1, C_2))$-bounded SoS polynomial;
    \item $p_1p_2$ is a $(k_1k_2,\,d_1 + d_2,\,(d_1 + d_2+1)2^{d_1 + d_2}C_1C_2)$-bounded SoS polynomial;
    \ewin{TODO: propagate this improvement to the rest of the paper}
    \item For any $t \in [0,1]$, $p_1((1 - t)x_1 + ty_1, (1 - t)x_2+ ty_2) $ is a $(k_1, d_1, C_1)$-bounded SoS polynomial in $x_1,y_1,x_2,y_2$.
\end{enumerate}
\end{claim}
\begin{proof}
For this proof, we let $[x_1^ix_2^j]p(x_1, x_2)$ denote the coefficient corresponding to $x_1^ix_2^j$ in $p$.

The first statement is obvious as we can simply combine the two representations as sums of squares.  The second also follows immediately by taking the two representations as sums of squares and expanding the product.
For this, we use that, when $r(x_1, x_2)$ is $(d_1, C_1)$-bounded and $s(x_1, x_2)$ is $(d_2, C_2)$-bounded, $rs$ is $(d_1+d_2, (d_1 + d_2 + 1)2^{d_1 + d_2}C_1C_2)$-bounded.
\begin{multline*}
    [x_1^ix_2^j](rs) = \sum_{\substack{0 \leq i' \leq i \\ 0 \leq j' \leq j}} \abs{[x_1^{i'}x_2^{j'}]r}\abs{[x_1^{i-i'}x_2^{j-j'}]s} \\
    \leq \sum_{\substack{0 \leq i' \leq i \\ 0 \leq j' \leq j}} \frac{C_1}{(i'+j')!}\frac{C_2}{(i+j-i' - j')!}
    = \frac{C_1 C_2}{(i+j)!}\sum_{\substack{0 \leq i' \leq i \\ 0 \leq j' \leq j}} \binom{i+j}{i' + j'}
    \leq \frac{C_1 C_2}{(i+j)!}(i+j+1)2^{i+j}
\end{multline*}
For the final statement, write
$p_1(x_1, x_2) = q_1(x_1,x_2)^2 + \dots + q_{k_1}(x_1,x_2)^2$.  Now we simply substitute in the change of variables.  A coefficient of the new polynomial is
\begin{multline*}
    [x_1^{i_1}y_1^{j_1}x_2^{i_2}y_2^{j_2}]q_{\ell}((1 - t)x_1 + ty_1, (1 - t)x_2+ ty_2) \\
    = 
    [x_1^{i_1 + j_1}x_2^{i_2 + j_2}]q_\ell(x_1, x_2) \cdot \binom{i_1 + j_1}{i_1} (1 - t)^{i_1} t^{j_1} \binom{i_2 + j_2}{i_2} (1 - t)^{i_2} t^{j_2} \leq [x_1^{i_1 + j_1}x_2^{i_2 + j_2}]q_\ell(x_1, x_2)
\end{multline*}
and this shows that after the change of variables, $p_1((1 - t)x_1 + ty_1, (1 - t)x_2+ ty_2) $ is still a $(k_1, d_1, C_1)$-bounded SoS polynomial.
\end{proof}

\begin{corollary}[Bounded coefficient Polynomials]\label{coro:bouned-sos-coeffs1}
Let $\ell$ be a positive integer and $-0.01 \leq c \leq 0.01$ be a real number.  Then, the polynomial
\[
s_{2\ell}(x) + c s_{2\ell -1}(x)
\]
is a $(2^\ell, \ell, 10^\ell)$-bounded SoS polynomial in $x$ (see Definition~\ref{def:sos-bounded-polynomial}).    
\end{corollary}
\begin{proof}
Note that all complex roots of $s_{2\ell}(x) + c s_{2\ell - 1}(x)$ have magnitude at most $5\ell$ by Claim~\ref{claim:bounded-roots}.  Also, by Claim~\ref{claim:compare-to-derivative}, none of the roots are real so by the Fundamental Theorem of Algebra, they come in conjugate pairs $z_1, \overline{z_1}, \dots , z_{\ell}, \overline{z_{\ell}}$.  Then, we can write 
\begin{equation}
s_{2\ell}(x) + c \ s_{2\ell - 1}(x){99} = \frac{1}{(2\ell)!} \prod_{j \in [\ell ]} (x - z_j)(x - \overline{z_j})  = \frac{1}{(2\ell)!} \prod_{j \in [\ell]} ((x - \Real(z_j))^2 + \Imag(z_j)^2)
\end{equation}
and now we can expand out the product above to get a sum of $2^\ell$ squares of polynomials of degree at most $\ell$.  Now we bound the coefficients of each of them.  For each monomial $x^k$, its coefficient has magnitude at most 
\begin{equation}
\binom{\ell}{k}\frac{(5\ell)^{\ell - k}}{\sqrt{(2l)!}} \leq  \frac{\ell^k}{k!} \frac{(10\ell)^{\ell - k}}{ \ell^{\ell}} = \frac{10^\ell}{k!} 
\end{equation}
and thus, we conclude that $s_{2\ell}(x) + c s_{2\ell - 1}(x)$ is a $(2^\ell, \ell, 10^\ell)$-bounded sum-of-squares polynomial.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
We focus on the expression \eqref{eqn:expanding-rxy}.(1).  The argument for \eqref{eqn:expanding-rxy}.(2)  is exactly the same. First, we show that expression \eqref{eqn:expanding-rxy}.(1) is non-negative. Using $1+a^2 = \frac{ (1+a)^2 + (1-a)^2}{2}$ and $a = \frac{ (1+a)^2 - (1-a)^2 }{4}$, 


\begin{equation}
\label{eqn:expanding-rxy-term1}
    \begin{split}
      \eqref{eqn:expanding-rxy}.(1) & = a^2 \cdot \int_{0}^{1} \Paren{ \Paren{0.998 + a^2 } p_{k,\ell}(z + ta ) - 0.001a (2-t) p'_{k,\ell}(z + ta) } dt   \\
      &  =  a^2 \cdot \int_{0}^{1} (2-t) \Paren{ \frac{ \Paren{1 + a^2 } }{8} p_{k,\ell}(z + ta ) -  \frac{ 0.001 ((1+a)^2 - (1-a)^2 )}{ 4}  p'_{k,\ell}(z + ta) } dt \\
      & \hspace{0.2in} +  a^2 \cdot \int_{0}^1 \Paren{ (0.998 + a^2) - \frac{ (2-t) (1+a^2) }{8 } p_{k,\ell}(z+ta) } dt  \\  
      & =   a^2 \cdot \int_{0}^{1} \frac{  (2-t) (1 + a)^2  }{16}  \Paren{    p_{k,\ell}(z + ta ) -  0.004 p'_{k,\ell}(z + ta)   } dt  \\
      & \hspace{0.2in}  + a^2 \cdot \int_{0}^{1} \frac{  (2-t) (1 - a)^2  }{16}  \Paren{    p_{k,\ell}(z + ta ) +  0.004 p'_{k,\ell}(z + ta)   } dt ,\\
      & \hspace{0.2in}  + a^2 \cdot \int_{0}^1 \Paren{ (0.998 + a^2) - \frac{ (2-t) (1+a^2) }{8 } } p_{k,\ell}(z+ta)  dt .
    \end{split}
\end{equation}





To prove nonnegativitiy, it suffices to show that $a_{k,\ell}(x) = p_{k,\ell}(x) - 0.004 p'_{k,\ell}(x)$ and $b_{k,\ell}(x) = p_{k,\ell}(x) +  0.004 p'_{k,\ell}(x)$ are non-negative for all $x \in \mathbb{R}$. 
Recall, $p_{k,\ell}(x) =  \prod_{j \in [k]} s_{2^j \ell} (x/k)$. Therefore, by product rule,
\begin{equation*}
\begin{split}
    p'_{k,\ell}(x) & = \sum_{j \in [k] }  \frac{ s'_{2^j \ell }(x/k) }{k}  \cdot \prod_{j'\neq j \in [k]} s_{2^{j'} \ell} (x/k)  \\
    & = \sum_{j \in [k] }  \frac{ s_{(2^j \ell)  - 1 }(x/k) }{k}  \cdot \prod_{j'\neq j \in [k]} s_{2^{j'} \ell} (x/k)   .
\end{split}
\end{equation*}
Therefore, 
\begin{equation}
    a_{k, \ell}(x) = \sum_{j \in [k]} \Paren{ \frac{ s_{2^j \ell }(x/k) - 0.004 \cdot s_{(2^j \ell) - 1}(x/k)  }{k}  }   \prod_{j'\neq j \in [k]} s_{2^{j'} \ell} (x/k)  \geq 0 
\end{equation}
since for all $j \in [k]$,  $s_{2^j \ell}(x/k) - 0.004 s_{ (2^j \ell)-1 }(x/k) \geq 0$ by Corollary~\ref{coro:bouned-sos-coeffs1} and $s_{2^{j'}  \ell  }(x/k) \geq 0$ by Corollary \ref{coro:positive-truncation}. Similarly, 
\begin{equation}
    b_{k,\ell}(x) = \sum_{j \in [k]} \Paren{ \frac{ s_{2^j \ell }(x/k) +  0.004 \cdot s_{(2^j \ell) - 1}(x/k)  }{k}  }   \prod_{j'\neq j \in [k]} s_{2^{j'} \ell} (x/k)  \geq 0
\end{equation}
since for all $j \in [k]$,  $s_{2^j \ell}(x/k) + 0.004 s_{ (2^j \ell)-1 }(x/k) \geq 0$ by Corollary~\ref{coro:bouned-sos-coeffs1}.  

Now we have proved that the expression is nonnegative, we show that it is a SoS polynomial with bounded coefficients.  By Corollary~\ref{coro:bouned-sos-coeffs1} the polynomials  
\[ s_{2^j \ell}(x/k) \pm 0.004 s_{ (2^j \ell)-1 }(x/k) , s_{2^j \ell}(x/k) \] are all
$(2^{2^{j-1}\ell}, 2^{j-1}\ell, 10^{2^{j-1}\ell})$-bounded SoS polynomials.  Thus, by Claim~\ref{claim:basic-composition-properties}, $a_{k,\ell}(x)$  and $b_{k,\ell}(x)$ are both $(k \cdot 2^{2^{k}\ell} , 2^k \ell, 90^{2^k\ell}) $-bounded SoS polynomials.  Since $z + ta = \frac{1 + t}{2} x + \frac{1 - t}{2} y$, by Claim~\ref{claim:basic-composition-properties} again, we get that for any real number $t \in [0,1]$, 
\[
\frac{  (2-t) (1 + a)^2  }{16}  \Paren{    p_{k,\ell}(z + ta ) -  0.004 p'_{k,\ell}(z + ta)   }
\]
is a $(k \cdot 2^{2^{k}\ell} , 2^k \ell, 100^{2^k\ell}) $-bounded SoS polynomial in the variables $x,y$ after substituting $z = (x+y)/2, a = (x-y)/2$.  We can use a similar argument for the other terms in the expression in \eqref{eqn:expanding-rxy-term1}.  Then we can use Claim~\ref{claim:sos-integration} to bound the integral over $t$ and deduce that the expression \eqref{eqn:expanding-rxy}.(1) is a $(10 \cdot (2^k \ell)^2 , 2^k \ell + 10, 150^{2^k\ell}) $-bounded SoS polynomial in the variables $x,y$.





\end{proof}
